INSERT INTO decks (id, owner_id, subject_id, name, origin, official_status, card_count, search_text)
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('698009f7-40d0-547b-9fdd-57c224498ea7', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quais são os fundamentos da República Federativa do Brasil?', 'Soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa, e pluralismo político.
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('362c275d-d24f-5964-ae66-68d9b795a230', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quais são os objetivos fundamentais da República Federativa do Brasil?', 'Construir uma sociedade livre, justa e solidária; garantir o desenvolvimento nacional; erradicar a pobreza e a marginalização e reduzir as desigualdades sociais e regionais; promover o bem de todos, sem preconceitos.
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('4e6e0b0f-90c3-5f71-9f69-4ae9bab8cd02', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quais são os Poderes da União e como a Constituição os qualifica?', 'Legislativo, Executivo e Judiciário, independentes e harmônicos entre si.', 'CF/88, art. 2º') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('ab8c837b-4eaa-5813-a570-42db69fb4bbb', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Em quais hipóteses é possível entrar na casa de alguém sem o consentimento do morador?', 'Em flagrante delito, em caso de desastre ou para prestar socorro (a qualquer hora); por determinação judicial, somente durante o dia.', 'CF/88, art. 5º, XI') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('f9445091-82a6-5db9-9e2f-76c8752c837e', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Qual remédio constitucional protege o direito líquido e certo não amparado por habeas corpus ou habeas data?', 'Mandado de segurança.', 'CF/88, art. 5º, LXIX') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('2cb5911c-9528-5584-9918-0879d9e59a7b', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quando cabe mandado de injunção?', 'Sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania.', 'CF/88, art. 5º, LXXI') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('59ad5b8a-5f5e-58e7-8c75-5b3e15553b8f', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quem pode impetrar mandado de segurança coletivo?', 'Partido político com representação no Congresso Nacional; organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa de seus membros ou associados.', 'CF/88, art. 5º, LXX') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('3ad480ad-7da8-5988-b386-373f00461e05', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quais ações constitucionais são gratuitas por disposição expressa?', 'Habeas corpus e habeas data (e, na forma da lei, os atos necessários ao exercício da cidadania). A ação popular é isenta de custas e ônus da sucumbência, salvo comprovada má-fé.', 'CF/88, art. 5º, LXXIII e LXXVII') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('b5b8ebfb-6e1e-5e79-bf32-4753c0590dc8', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quais cargos são privativos de brasileiro nato?', 'Presidente e Vice-Presidente da República; Presidente da Câmara dos Deputados; Presidente do Senado Federal; Ministro do STF; carreira diplomática; oficial das Forças Armadas; Ministro de Estado da Defesa.', 'CF/88, art. 12, § 3º') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('10d0805e-76b0-5d75-8b66-acd7d3f49082', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Qual a idade mínima para Presidente, Senador, Governador, Deputado, Prefeito e Vereador?', '35 anos: Presidente, Vice e Senador.
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('cc61bf45-0b31-51c0-955d-8a4bf0fdd78a', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Quais são os direitos sociais listados no art. 6º?', 'Educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância, e assistência aos desamparados.', 'CF/88, art. 6º') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('1954b639-38a1-5ea8-b588-1ad97e93928b', '7539640e-6257-54f4-8b3d-a3fbc035e942', 'Após quanto tempo o servidor nomeado para cargo efetivo em virtude de concurso adquire estabilidade?', 'Após 3 anos de efetivo exercício, sendo obrigatória a avaliação especial de desempenho por comissão instituída para essa finalidade.', 'CF/88, art. 41') ON CONFLICT (id) DO NOTHING;
INSERT INTO decks (id, owner_id, subject_id, name, origin, official_status, card_count, search_text)
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('596a141e-c060-5464-8783-d0f0628782aa', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são os princípios expressos no caput do art. 37 da CF/88?', 'Legalidade, impessoalidade, moralidade, publicidade e eficiência (LIMPE). A eficiência foi incluída pela EC 19/1998.', 'CF/88, art. 37') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('23a77dd0-ca4c-5cdd-8e0b-a535921ed328', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são os atributos do ato administrativo?', 'Presunção de legitimidade (e veracidade), imperatividade, autoexecutoriedade e tipicidade.
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('461af946-286d-53be-8abe-2310f4977815', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são os elementos do ato administrativo e quais podem ser discricionários?', 'Competência, finalidade, forma, motivo e objeto. Competência, finalidade e forma são vinculados; motivo e objeto compõem o mérito e podem ser discricionários.', 'Lei 4.717/65, art. 2º') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('d75c8abf-3eff-5067-a214-32a5361d9614', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Diferença entre anulação e revogação de ato administrativo?', 'Anulação: por ilegalidade, efeitos ex tunc, pela Administração ou pelo Judiciário.
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('6a1fbc75-7ab9-5785-ba11-ebfc7dcbd7de', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Qual o prazo para a Administração anular atos de que decorram efeitos favoráveis aos destinatários?', '5 anos, contados da data em que foram praticados, salvo comprovada má-fé.', 'Lei 9.784/99, art. 54') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('0de81d22-55a1-5f23-bd20-a10ee1760c5d', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são as formas de provimento de cargo público na Lei 8.112/90?', 'Nomeação, promoção, readaptação, reversão, aproveitamento, reintegração e recondução.', 'Lei 8.112/90, art. 8º') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('1c1685cc-fc22-5408-a556-bfc3a7736467', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais os prazos para posse e para entrar em exercício na Lei 8.112/90?', 'Posse: 30 dias contados da publicação do ato de provimento.
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('e6b8bb2d-b82c-51e1-a22c-cee81df268ba', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Qual é a duração do estágio probatório na Lei 8.112/90?', 'O texto da lei fala em 24 meses, mas STF e STJ entendem que o estágio acompanha o prazo da estabilidade: 3 anos (CF, art. 41). Atenção ao que a questão pede: letra da lei ou jurisprudência.', 'Lei 8.112/90, art. 20') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('d98d5832-4a6b-5948-8265-a864d3056688', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são as formas de vacância do cargo público?', 'Exoneração, demissão, promoção, readaptação, aposentadoria, posse em outro cargo inacumulável e falecimento.', 'Lei 8.112/90, art. 33') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('43025569-8da3-5f56-b973-3eade01def48', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são as penalidades disciplinares da Lei 8.112/90?', 'Advertência, suspensão, demissão, cassação de aposentadoria ou disponibilidade, destituição de cargo em comissão e destituição de função comissionada.', 'Lei 8.112/90, art. 127') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('179ab7c2-b6e0-5988-a42f-fe2c2a0a26ba', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Qual o prazo máximo da penalidade de suspensão?', '90 dias.', 'Lei 8.112/90, art. 130') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('9c6d260e-3147-5fa5-ab1a-d49f13ef3226', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são os atributos do poder de polícia?', 'Discricionariedade, autoexecutoriedade e coercibilidade.', 'Doutrina') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('c171f036-02c5-59d8-b385-35ac653a4998', 'a326b0de-c511-5395-ae2b-7dbecb0671b5', 'Quais são as modalidades de licitação na Lei 14.133/2021?', 'Pregão, concorrência, concurso, leilão e diálogo competitivo. Tomada de preços e convite deixaram de existir.', 'Lei 14.133/2021, art. 28') ON CONFLICT (id) DO NOTHING;
INSERT INTO decks (id, owner_id, subject_id, name, origin, official_status, card_count, search_text)
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('f73e57dc-eba4-5343-9e7a-2c08ffc68acf', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Ocorre crase antes de palavra masculina?', 'Em regra, não. Exceção: quando está subentendida a expressão “à moda de” — “bife à milanesa”, “sapato à Luís XV”.', 'Crase') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('cba84a8a-b520-56db-9e5c-91c7a9825333', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Ocorre crase antes de verbo?', 'Nunca. “Começou a estudar”, “Estava disposto a ceder”.', 'Crase') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('d7a48506-52f1-54f1-8305-b6a82f3ae1ed', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Em quais casos a crase é facultativa?', 'Antes de pronome possessivo feminino no singular (“à sua casa” / “a sua casa”), antes de nome próprio feminino de pessoa (“à Maria” / “a Maria”) e depois de “até” (“até à praia” / “até a praia”).', 'Crase') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('ee944899-34fa-5ca7-baf8-88393710bfe5', 'c8744e22-abe0-583f-a4c5-68e44aa12680', '“Das 8h às 18h” ou “de 8h às 18h”?', '“Das 8h às 18h” (com artigo nos dois) ou “de 8h a 18h” (sem artigo nos dois). Misturar — “de 8h às 18h” — é considerado erro.', 'Crase') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('0aa5d3ed-73ca-55c6-821e-ca76a21bc2b9', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Qual a regência de “assistir” no sentido de ver, presenciar?', 'Transitivo indireto, com a preposição “a”: “Assisti ao filme”. No sentido de ajudar, é transitivo direto: “O médico assistiu o paciente”.', 'Regência verbal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('377c68b1-c6d8-527b-a6b3-dde14f6fcb96', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Como se usa corretamente o verbo “preferir”?', 'Prefere-se uma coisa a outra: “Prefiro café a chá”. Evite “preferir mais” e “do que”.', 'Regência verbal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('3758a649-b921-5d72-a1cc-9e6103d96e49', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Qual a regência de “obedecer” e “desobedecer”?', 'Transitivos indiretos, com a preposição “a”: “Obedeça ao regulamento”.', 'Regência verbal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('1f4afe21-d4f3-5873-b8f9-482387750477', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Qual a regência de “implicar” no sentido de acarretar?', 'Transitivo direto, sem preposição, pela norma tradicional: “A decisão implica mudanças” (e não “implica em mudanças”).', 'Regência verbal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('0977e79f-24f6-5a01-a7e3-f78b8c57bb58', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Como concorda o verbo “haver” no sentido de existir?', 'É impessoal: fica na 3ª pessoa do singular, e o auxiliar acompanha. “Havia muitos candidatos.” “Deve haver soluções.”', 'Concordância verbal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('f9ee37f9-525f-5e34-9de9-ed9f8149fb1b', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Como concorda o verbo “fazer” indicando tempo decorrido?', 'É impessoal, fica no singular: “Faz dois anos que estudo para este concurso.”', 'Concordância verbal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('5ec59489-848e-5b7a-847e-451f50cd90b1', 'c8744e22-abe0-583f-a4c5-68e44aa12680', '“Seguem anexo as planilhas” está correto?', 'Não. “Anexo” é adjetivo e concorda com o nome: “Seguem anexas as planilhas”. A locução “em anexo” é invariável.', 'Concordância nominal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('3e0de373-f6bf-572f-909b-b4c1d5902ac9', 'c8744e22-abe0-583f-a4c5-68e44aa12680', '“Meio” varia em gênero e número?', 'Como advérbio (“um pouco”), é invariável: “Ela está meio cansada”. Como numeral (“metade”), concorda: “meia hora”, “meias palavras”.', 'Concordância nominal') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('92a3360f-25e9-5c35-a0a0-24943118a033', 'c8744e22-abe0-583f-a4c5-68e44aa12680', 'Quando usar “por que”, “por quê”, “porque” e “porquê”?', '“Por que”: perguntas e “pelo qual” (“Por que desistiu?”).
INSERT INTO decks (id, owner_id, subject_id, name, origin, official_status, card_count, search_text)
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('4f205ef3-88d1-5cba-9925-2b5e83425053', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Qual a negação de “p e q”?', '“não p ou não q” (~p ∨ ~q) — Lei de De Morgan.', 'Lógica proposicional') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('11eebbbe-5eff-5f96-af4d-54e1cc43e9d7', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Qual a negação de “p ou q”?', '“não p e não q” (~p ∧ ~q) — Lei de De Morgan.', 'Lógica proposicional') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('ea599d5d-733c-5435-b889-ea78874f1cc6', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Qual a negação de “Se p, então q”?', '“p e não q” (p ∧ ~q). Mantém o antecedente e nega o consequente.', 'Lógica proposicional') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('914bfb88-766a-5704-8278-c3078c62ae47', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Quais são as equivalências mais cobradas de “Se p, então q”?', 'Contrapositiva: “Se não q, então não p” (~q → ~p).
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('0e519e32-19b8-56e1-9be5-257ea0601747', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Quando a condicional “p → q” é falsa?', 'Somente quando p é verdadeira e q é falsa (“Vera Fischer é falsa”).', 'Tabela-verdade') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('d9e103d7-1d4b-598c-8df7-1c0bb055b100', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Quando a bicondicional “p ↔ q” é verdadeira?', 'Quando p e q têm o mesmo valor lógico (ambas verdadeiras ou ambas falsas).', 'Tabela-verdade') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('66c5c694-b63f-5237-a5e1-361cbf3dc453', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Diferença entre “p ou q” e “ou p ou q”?', '“p ou q” (inclusiva) é falsa só quando ambas são falsas.
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('5825b4b0-fbd5-55a5-ba09-891b4ecb0cc8', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Qual a negação de “ou p ou q” (disjunção exclusiva)?', '“p se e somente se q” (p ↔ q).', 'Lógica proposicional') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('619c37a5-70cd-5925-8595-9e85cd90ab1a', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Qual a negação de “Todo A é B”?', '“Algum A não é B” (existe pelo menos um A que não é B).', 'Lógica de argumentação') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('daf3808e-051d-513e-aff4-ca6a446464b5', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Qual a negação de “Nenhum A é B”?', '“Algum A é B”.', 'Lógica de argumentação') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('5722c30d-6cb6-54bf-b9a4-cd2025b9cc53', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Qual a negação de “Algum A é B”?', '“Nenhum A é B”.', 'Lógica de argumentação') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('c570c6f1-d4af-5707-a599-48e2932300c6', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'Quantas linhas tem a tabela-verdade de uma proposição com n proposições simples?', '2ⁿ linhas. Ex.: 3 proposições simples → 8 linhas.', 'Tabela-verdade') ON CONFLICT (id) DO NOTHING;
INSERT INTO cards (id, deck_id, front, back, source) VALUES ('3091c1f8-5476-5c01-9352-c827e59e0b4d', '9d10ae27-4a15-5c51-92d4-f5a2abde32e8', 'O que são tautologia e contradição?', 'Tautologia: proposição composta sempre verdadeira (ex.: p ∨ ~p).
